import { NodeStreamsTransport } from '@enkaku/node-streams-transport';
import { createValidator } from '@enkaku/schema';
import { clientMessage, INVALID_PARAMS, LATEST_PROTOCOL_VERSION, METHOD_NOT_FOUND } from '@mokei/context-protocol';
import { ContextRPC, RPCError } from '@mokei/context-rpc';
import { toResourceHandlers } from './definitions.js';
// cf https://datatracker.ietf.org/doc/html/rfc5424#section-6.2.1
const LOGGING_LEVELS = {
    emergency: 0,
    alert: 1,
    critical: 2,
    error: 3,
    warning: 4,
    notice: 5,
    info: 6,
    debug: 7
};
const validateClientMessage = createValidator(clientMessage);
export class ContextServer extends ContextRPC {
    #capabilities = {};
    #client;
    #clientInitialize;
    #clientLoggingLevel;
    #completeHandler;
    #serverInfo;
    #promptHandlers = {};
    #promptsList = [];
    #resources;
    #toolHandlers = {};
    #toolsList = [];
    constructor(params){
        super({
            transport: params.transport,
            validateMessageIn: validateClientMessage
        });
        this.#client = {
            createMessage: this.createMessage.bind(this),
            elicit: this.elicit.bind(this),
            listRoots: this.listRoots.bind(this),
            log: this.log.bind(this)
        };
        this.#completeHandler = params.complete;
        this.#serverInfo = {
            name: params.name,
            version: params.version
        };
        for (const [name, prompt] of Object.entries(params.prompts ?? {})){
            const { handler, ...info } = prompt;
            this.#promptHandlers[name] = handler;
            this.#promptsList.push({
                name,
                ...info
            });
        }
        if (this.#promptsList.length !== 0) {
            this.#capabilities.prompts = {};
        }
        if (params.resources != null) {
            this.#capabilities.resources = {};
            this.#resources = toResourceHandlers(params.resources);
        }
        for (const [name, tool] of Object.entries(params.tools ?? {})){
            const { handler, ...info } = tool;
            this.#toolHandlers[name] = handler;
            this.#toolsList.push({
                name,
                ...info
            });
        }
        if (this.#toolsList.length !== 0) {
            this.#capabilities.tools = {};
        }
        this._handle();
    }
    get clientInitialize() {
        return this.#clientInitialize;
    }
    log(level, data, logger) {
        this.events.emit('log', {
            level,
            data,
            logger
        });
    }
    elicit(params) {
        return this.request('elicitation/create', params);
    }
    listRoots(params = {}) {
        return this.request('roots/list', params);
    }
    createMessage(params) {
        return this.request('sampling/createMessage', params);
    }
    _handle() {
        this.events.on('log', (log)=>{
            // Only send log if client has opted-in and it's at least as verbose as the client has requested
            if (this.#clientLoggingLevel != null && LOGGING_LEVELS[log.level] <= LOGGING_LEVELS[this.#clientLoggingLevel]) {
                this._write({
                    jsonrpc: '2.0',
                    method: 'notifications/message',
                    params: log
                });
            }
        });
        super._handle();
    }
    _handleNotification(notification) {
        switch(notification.method){
            case 'notifications/initialized':
                this.events.emit('initialized');
                break;
        }
    }
    async _handleRequest(request, signal) {
        switch(request.method){
            case 'completion/complete':
                if (this.#completeHandler == null) {
                    break;
                }
                return await this.#completeHandler({
                    client: this.#client,
                    params: request.params,
                    signal
                });
            case 'initialize':
                this.#clientInitialize = request.params;
                this.events.emit('initialize', request.params);
                return {
                    capabilities: this.#capabilities,
                    protocolVersion: LATEST_PROTOCOL_VERSION,
                    serverInfo: this.#serverInfo
                };
            case 'logging/setLevel':
                this.#clientLoggingLevel = request.params.level;
                return {};
            case 'prompts/get':
                return await this.#getPrompt(request, signal);
            case 'prompts/list':
                return {
                    prompts: this.#promptsList
                };
            case 'resources/list':
                if (this.#resources == null) {
                    break;
                }
                return this.#resources.list({
                    client: this.#client,
                    params: request.params,
                    signal
                });
            case 'resources/read':
                if (this.#resources == null) {
                    break;
                }
                return this.#resources.read({
                    client: this.#client,
                    params: request.params,
                    signal
                });
            case 'resources/templates/list':
                if (this.#resources == null) {
                    break;
                }
                return this.#resources.listTemplates({
                    client: this.#client,
                    params: request.params,
                    signal
                });
            case 'tools/call':
                return await this.#callTool(request, signal);
            case 'tools/list':
                return {
                    tools: this.#toolsList
                };
        }
        throw new RPCError(METHOD_NOT_FOUND, `Unsupported method: ${request.method}`);
    }
    async #callTool(request, signal) {
        const handler = this.#toolHandlers[request.params.name];
        if (handler == null) {
            throw new RPCError(INVALID_PARAMS, `Tool ${request.params.name} not found`);
        }
        return await handler({
            arguments: request.params.arguments ?? {},
            client: this.#client,
            signal
        });
    }
    async #getPrompt(request, signal) {
        const handler = this.#promptHandlers[request.params.name];
        if (handler == null) {
            throw new RPCError(INVALID_PARAMS, `Prompt ${request.params.name} not found`);
        }
        return await handler({
            arguments: request.params.arguments,
            client: this.#client,
            signal
        });
    }
}
export function serveProcess(config) {
    const transport = new NodeStreamsTransport({
        streams: {
            readable: process.stdin,
            writable: process.stdout
        }
    });
    return new ContextServer({
        ...config,
        transport
    });
}
